import{_ as t,C as r,o as i,c as n,a2 as e,E as s}from"./chunks/framework.CTsVsvlS.js";const f=JSON.parse('{"title":"iOS 常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ios/faq.md","filePath":"guide/ios/faq.md"}'),l={name:"guide/ios/faq.md"};function h(d,a,p,_,c,u){const o=r("GuideShot");return i(),n("div",null,[a[0]||(a[0]=e('<h1 id="ios-常见问题" tabindex="-1">iOS 常见问题 <a class="header-anchor" href="#ios-常见问题" aria-label="Permalink to &quot;iOS 常见问题&quot;">​</a></h1><h2 id="为什么只显示少量照片" tabindex="-1">为什么只显示少量照片？ <a class="header-anchor" href="#为什么只显示少量照片" aria-label="Permalink to &quot;为什么只显示少量照片？&quot;">​</a></h2><p>拾光可能只获得了有限访问权限。点图库顶部 <strong>仅限所选照片 · 管理访问权限</strong>，或在 iPhone、iPad 的系统设置中调整拾光的照片权限。也检查当前相簿或媒体类型。<a href="./../ios.html#授权范围与更多照片">连接照片图库</a></p><h2 id="为什么滑动照片时只是在移动画面" tabindex="-1">为什么滑动照片时只是在移动画面？ <a class="header-anchor" href="#为什么滑动照片时只是在移动画面" aria-label="Permalink to &quot;为什么滑动照片时只是在移动画面？&quot;">​</a></h2><p>照片放大后，单指拖动用于看局部。先缩小到适合窗口，再左右或上下滑。也可以单点照片显示操作栏，通过按钮整理。</p><h2 id="为什么上滑和下滑跟手册不一样" tabindex="-1">为什么上滑和下滑跟手册不一样？ <a class="header-anchor" href="#为什么上滑和下滑跟手册不一样" aria-label="Permalink to &quot;为什么上滑和下滑跟手册不一样？&quot;">​</a></h2><p>手势可以自定义。在 <strong>设置 → 手势</strong> 检查两个方向的当前动作，或打开 <strong>用法指引</strong> 看实时提示。</p><h2 id="哪些数据会同步到其他设备" tabindex="-1">哪些数据会同步到其他设备？ <a class="header-anchor" href="#哪些数据会同步到其他设备" aria-label="Permalink to &quot;哪些数据会同步到其他设备？&quot;">​</a></h2><p>相簿、收藏和确认后的图库删除由 Apple「照片」按系统的 iCloud 设置同步。保留、待删除队列、统计和相簿显示选项保存在当前设备。</p>',9)),s(o,{src:"ios/privacy.jpg",alt:"iPhone 内的隐私信息页，说明照片权限、本机数据、iCloud 和地图。",caption:"可从设置中的照片与隐私打开说明。",variant:"phone"}),a[1]||(a[1]=e('<h2 id="云端照片下载失败怎么办" tabindex="-1">云端照片下载失败怎么办？ <a class="header-anchor" href="#云端照片下载失败怎么办" aria-label="Permalink to &quot;云端照片下载失败怎么办？&quot;">​</a></h2><p>检查网络连接，在当前预览点 <strong>重试</strong>。仅在 iCloud 的普通视频可先用 Apple「照片」下载。<a href="./media.html">预览、媒体与地图</a></p><h2 id="找不到某个相簿怎么办" tabindex="-1">找不到某个相簿怎么办？ <a class="header-anchor" href="#找不到某个相簿怎么办" aria-label="Permalink to &quot;找不到某个相簿怎么办？&quot;">​</a></h2><p>到 <strong>更多操作 → 选择显示的相簿</strong> 检查它是否勾选。部分共享或系统相簿可能限制归类。<a href="./albums.html">相簿与批量归类</a></p>',4))])}const q=t(l,[["render",h]]);export{f as __pageData,q as default};
